## 인가 전략

### RBAC vs ABAC

| 방식 | 설명 | 적합한 경우 |
|------|------|-----------|
| **RBAC** | 역할(Role) 기반 | 역할이 명확히 구분되는 시스템 |
| **ABAC** | 속성(Attribute) 기반 | 복잡한 조건이 필요한 시스템 |

### @PreAuthorize 커스텀 표현식

```kotlin
@RestController
@RequestMapping("/api/orders")
class OrderController(private val orderService: OrderService) {

    @PreAuthorize("hasRole('USER')")
    @PostMapping
    fun createOrder(@RequestBody command: OrderCommand): OrderResponse {
        return orderService.createOrder(command)
    }

    // 커스텀 SpEL: 본인 주문만 조회 가능
    @PreAuthorize("@orderSecurity.isOwner(authentication, #orderId)")
    @GetMapping("/{orderId}")
    fun getOrder(@PathVariable orderId: Long): OrderResponse {
        return orderService.getOrder(orderId)
    }

    @PreAuthorize("hasRole('ADMIN') or @orderSecurity.isOwner(authentication, #orderId)")
    @DeleteMapping("/{orderId}")
    fun cancelOrder(@PathVariable orderId: Long) {
        orderService.cancelOrder(orderId)
    }
}

@Component("orderSecurity")
class OrderSecurityEvaluator(private val orderRepository: OrderRepository) {
    fun isOwner(authentication: Authentication, orderId: Long): Boolean {
        val userId = (authentication.principal as UserDetails).username.toLong()
        val order = orderRepository.findById(orderId) ?: return false
        return order.userId == userId
    }
}
```

